from rest_framework.response import Response

from care.action_evaluator.base import ActionEvaluator
from care.emr.models.action import Action
from care.utils.shortcuts import get_object_or_404


class ExecuteAction(BaseModel):
    action: UUID4


class EMRActionBaseViewSet:
    # On save, get all actions and perform it.
    ACTIONS_ENABLED = True
    ACTION_CONTEXT = None
    ACTION_CONTEXT_CLASS = None
    PERFORM_INDEPENDENT_ACTIONS = False

    def get_facility_from_instance(self, instance):
        return None

    def get_additional_actions(self, instance):
        return []

    def perform_actions(self, instance):
        facility = self.get_facility_from_instance(instance)
        actions_list = Action.get_actions_for_context(self.ACTION_CONTEXT, facility)
        extra_actions = self.get_additional_actions(instance)
        all_actions = actions_list + extra_actions
        responses = []
        for actions in all_actions:
            response = ActionEvaluator(
                self.request,
                self.request.user,
                self.ACTION_CONTEXT_CLASS.context_type,
                instance,
                actions,
            ).evaluate()
            responses.append(response)
        return responses

    @extend_schema(
        request=ExecuteAction,
    )
    @action(methods=["POST"], detail=True)
    def execute_action(self, request, *args, **kwargs):
        if not self.PERFORM_INDEPENDENT_ACTIONS:
            raise ValidationError("This action is not performable independently")
        request_params = ExecuteAction(**request.data)
        action = get_object_or_404(
            Action.objects.filter(performable=True, action_context=self.ACTION_CONTEXT),
            external_id=request_params.action,
        )
        instance = self.get_object()
        self.authorize_update(request, instance)
        # TODO: Authorize action permission
        response = ActionEvaluator(
            request,
            request.user,
            self.ACTION_CONTEXT_CLASS.context_type,
            instance,
            action.actions,
        ).evaluate()
        return Response(response)
from django.contrib.postgres.fields import ArrayField
from django.core.cache import cache
from django.db import models

from care.emr.models.base import EMRBaseModel

ACTION_CACHE_KEY = "action:cache:context:{context}:facility:{facility}"


class Action(EMRBaseModel):
    name = models.CharField(max_length=255)
    description = models.TextField()
    action_context = models.CharField(max_length=255)
    actions = models.JSONField()
    facility = models.ForeignKey(
        "facility.Facility", on_delete=models.CASCADE, null=True, blank=True
    )
    performable = models.BooleanField(default=True)
    organization_cache = ArrayField(models.IntegerField(), default=list)
    internal_organization_cache = ArrayField(models.IntegerField(), default=list)

    def save(self, *args, **kwargs):
        self.invalidate_cache()
        super().save(*args, **kwargs)

    def invalidate_instance_cache(self):
        cache.delete(ACTION_CACHE_KEY.format(context=self.action_context, facility=""))

    def invalidate_facility_cache(self):
        cache.delete(
            ACTION_CACHE_KEY.format(
                context=self.action_context, facility=self.facility_id
            )
        )

    def invalidate_cache(self):
        if self.facility:
            self.invalidate_facility_cache()
        self.invalidate_instance_cache()

    @classmethod
    def get_instance_actions(cls, context):
        cache_key = ACTION_CACHE_KEY.format(context=context, facility="")
        cached_data = cache.get(cache_key)
        if cached_data:
            return cached_data
        actions = list(
            cls.objects.filter(
                action_context=context, facility__isnull=True
            ).values_list("actions", flat=True)
        )
        cache.set(cache_key, actions, 60 * 60 * 24)
        return actions

    @classmethod
    def get_facility_actions(cls, context, facility):
        cache_key = ACTION_CACHE_KEY.format(context=context, facility=facility.id)
        cached_data = cache.get(cache_key)
        if cached_data:
            return cached_data
        actions = list(
            cls.objects.filter(action_context=context, facility=facility).values_list(
                "actions", flat=True
            )
        )
        cache.set(cache_key, actions, 60 * 60 * 24)
        return actions

    @classmethod
    def get_actions_for_context(cls, context, facility):
        return cls.get_instance_actions(context) + cls.get_facility_actions(
            context, facility
        )
