        bulk = []
        for permission in permissions:
            permission_obj, _ = PermissionModel.objects.get_or_create(
                slug=permission,
                defaults=model_to_dict(baker.prepare(PermissionModel, slug=permission)),
            )
            bulk.append(RolePermission(role=role, permission=permission_obj))
        RolePermission.objects.bulk_create(bulk)

        # bulk_create wasn't triggering post_save, so manually clearing cache
        cache.delete(ROLE_PERMISSIONS_CACHE_KEY.format(role.id))
        cache.delete(ROLE_PERMISSION_SK_CACHE_KEY.format(role.id))
        return role

    def create_patient(self, **kwargs):
        from care.emr.models import Patient

        return baker.make(Patient, **kwargs)

    def create_facility(self, user, **kwargs):
        from care.facility.models.facility import Facility

        return baker.make(Facility, created_by=user, **kwargs)

    def create_encounter(self, patient, facility, organization, status=None, **kwargs):
        from care.emr.models import Encounter
        from care.emr.models.encounter import EncounterOrganization
        from care.emr.resources.encounter.constants import StatusChoices

        data = {
            "patient": patient,
            "facility": facility,
            "status": status or StatusChoices.in_progress.value,
            "encounter_class": choice(list(ClassChoices)).value,
            "priority": choice(list(EncounterPriorityChoices)).value,
        }

        data.update(**kwargs)

        encounter = baker.make(
            Encounter,
            **data,
        for action in self.actions:
            if action.condition and self.evaluate_condition(action.condition):
                for instruction in action.instructions:
                    outputs = self.evaluate_instruction(instruction)
                    results.append(outputs)
        return results

    def evaluate_instruction(self, instruction: Instruction):
        instruction_context = instruction.context
        self.evaluate_field(instruction_context, context_mode=True)
        context = self.context_cache[instruction_context]
        for field, value in instruction.params.items():
            if (
                isinstance(value, str)
                and value.startswith("{{")
                and value.endswith("}}")
            ):
                field_name = value[2:-2]
                self.evaluate_field(field_name)
                instruction.params[field] = Expr(
                    field_name.strip(), model=expression_model
                ).eval(self.field_cache)
        instruction_class = ActionInstructionRegistry.get_instruction(instruction.slug)
        if not instruction_class:
            err = f"Instruction {instruction.slug} not found"
            raise ValueError(err)
        instruction_instance = instruction_class(
            self.request,
            self.user,
            context,
            instruction.params,
            self.field_cache,
            self.cache,
        )
        return instruction_instance.do_evaluate()


