import { Check, Trash2 } from "lucide-react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

import ValueSetSelect from "@/components/Questionnaire/ValueSetSelect";

import { CollapsibleSettingsCard } from "@/components/QuestionnaireV2/shared/CollapsibleSettingsCard";

import { Code, ValueSetSystem } from "@/types/base/code/code";
import { Question } from "@/types/questionnaire/question";
import { TERMINOLOGY_SYSTEMS } from "@/types/valueSet/valueSet";

/**
 * Backend observation valueset for `Question.code`; arbitrary manually-typed
 * codes are rejected at save time, so this card only offers search selection.
 */
const OBSERVATION_VALUESET_SLUG: ValueSetSystem = "system-observation";

/** "http://loinc.org" -> "LOINC"; unknown systems fall back to the raw URI. */
function systemLabel(system: string): string {
  const entry = Object.entries(TERMINOLOGY_SYSTEMS).find(
    ([, url]) => url === system,
  );
  return entry ? entry[0] : system;
}

interface QuestionCodingCardProps {
  question: Question;
  onChange: (patch: Partial<Question>) => void;
  /** Render the coding editor without the collapsible card shell — the
   *  studio inspector hosts it flat inside its Coding tab, with the
   *  "Code Verified" badge folded into the bound-code row. */
  bare?: boolean;
}

export function QuestionCodingCard({
  question,
  onChange,
  bare = false,
}: QuestionCodingCardProps) {
  const { t } = useTranslation();
  const code = question.code;

  const handleSelect = (selected: Code) => {
    // Straight from the valueset expansion — membership is guaranteed, so
    // the code is verified by construction (no manual verify step).
    onChange({
      code: {
        system: selected.system,
        code: selected.code,
        display: selected.display,
      },
    });
  };

  const content = code?.code ? (
    <div className="flex flex-wrap items-center gap-x-3 gap-y-2 rounded-md border border-gray-200 bg-gray-50 p-3">
      {/* Bare (tab) mode has no card title carrying "LOINC: 8867-4" — the
          row itself shows the combined system+code string. */}
      {bare ? (
        <span className="font-mono text-sm font-semibold text-gray-900">
          {`${systemLabel(code.system)}: ${code.code}`}
        </span>
      ) : (
        <>
          <Badge variant="outline">{systemLabel(code.system)}</Badge>
          <span className="font-mono text-sm text-gray-900">{code.code}</span>
        </>
      )}
      {bare && (
        <Badge variant="green">
          <Check className="size-3" />
          {t("code_verified")}
        </Badge>
      )}
      <span className="w-full min-w-0 break-words text-sm text-gray-600">
        {code.display}
      </span>
      <div className="flex shrink-0 items-center gap-1">
        <ValueSetSelect
          system={OBSERVATION_VALUESET_SLUG}
          value={null}
          placeholder={t("change")}
          aria-label={t("change")}
          onSelect={handleSelect}
          showCode
          variant="ghost"
          size="sm"
          className="font-medium text-gray-700"
        />
        <Button
          type="button"
          variant="ghost"
          size="sm"
          className="text-red-600 hover:bg-red-50 hover:text-red-700"
          onClick={() => onChange({ code: undefined })}
        >
          <Trash2 className="size-4" />
          {t("remove")}
        </Button>
      </div>
    </div>
  ) : (
    <div className="space-y-3">
      <p className="text-sm text-gray-500">{t("question_coding_explainer")}</p>
      <ValueSetSelect
        system={OBSERVATION_VALUESET_SLUG}
        value={null}
        placeholder={t("search_for_observation_codes")}
        aria-label={t("search_for_observation_codes")}
        onSelect={handleSelect}
        showCode
        className="w-full"
      />
    </div>
  );

  if (bare) return content;

  return (
    <CollapsibleSettingsCard
      title={
        code?.code
          ? `${systemLabel(code.system)}: ${code.code}`
          : t("coding_details")
      }
      subtitle={code?.display}
      badge={
        code?.code ? (
          <Badge variant="green">
            <Check className="size-3" />
            {t("code_verified")}
          </Badge>
        ) : undefined
      }
    >
      {content}
    </CollapsibleSettingsCard>
  );
}
import { useQuery } from "@tanstack/react-query";
import { TFunction } from "i18next";

import {
  ValueSetAuthContext,
  ValueSetRead,
  ValueSetStatus,
} from "@/types/valueSet/valueSet";
import valueSetApi from "@/types/valueSet/valueSetApi";
import query from "@/Utils/request/query";

export interface ScopedValueSet {
  valueset: ValueSetRead;
  /** Which list the set came from. `ValueSetReadSpec` does not return
   *  `auth_context`, so this is the only scope signal the UI has. */
  authContext: Extract<ValueSetAuthContext, "instance" | "facility">;
}

/** Where a value set lives, as a label. Only ever shown where the two
 *  lists are merged — an instance set and a facility override of it
 *  usually share a name. */
export function scopeLabel(
  authContext: ScopedValueSet["authContext"],
  t: TFunction,
): string {
  return t(authContext === "facility" ? "this_facility" : "instance");
}

/** `Name (This facility)` — the merged-list option label. */
export function scopedOptionLabel(
  { valueset, authContext }: ScopedValueSet,
  t: TFunction,
): string {
  return `${valueset.name} (${scopeLabel(authContext, t)})`;
}

const PAGE = 50;

/**
 * Active value sets a picker inside `facilityId` (or the admin area, when
 * undefined) may choose from: the instance-level sets, plus — inside a
 * facility — that facility's own sets, listed first. Two requests because
 * the list endpoint filters by either `auth_context` or `facility` and its
 * read spec carries neither back.
 */
export function useScopedValueSets({
  facilityId,
  search,
}: {
  facilityId?: string;
  search: string;
}): { options: ScopedValueSet[]; isFetching: boolean } {
  const params = {
    name: search || undefined,
    status: ValueSetStatus.ACTIVE,
    limit: PAGE,
  };

  const instance = useQuery({
    queryKey: ["valuesets", "scoped", "instance", search],
    queryFn: query.debounced(valueSetApi.list, {
      queryParams: { ...params, auth_context: "instance" },
    }),
  });

  const facility = useQuery({
    queryKey: ["valuesets", "scoped", "facility", facilityId, search],
    queryFn: query.debounced(valueSetApi.list, {
      queryParams: { ...params, facility: facilityId },
    }),
    enabled: !!facilityId,
  });

  const options: ScopedValueSet[] = [
    ...(facility.data?.results ?? []).map((valueset) => ({
      valueset,
      authContext: "facility" as const,
    })),
    ...(instance.data?.results ?? []).map((valueset) => ({
      valueset,
      authContext: "instance" as const,
    })),
  ];

  return {
    options,
    isFetching: instance.isFetching || facility.isFetching,
  };
}
