import { expect, test } from "@playwright/test";
import {
  addTopLevelQuestion,
  createQuestionnaireAndOpenBuilder,
} from "tests/helper/questionnaireV2";

test.use({ storageState: "tests/.auth/user.json" });

test("admin navigation indicates overflow and explains the header search", async ({
  page,
  context,
  baseURL,
}) => {
  await context.addCookies([
    { name: "sidebar:state", value: "true", url: baseURL! },
  ]);
  await page.setViewportSize({ width: 1280, height: 440 });
  await page.goto("/admin/questionnaires");
  const content = page.locator('[data-sidebar="content"]');
  const more = page.getByRole("button", { name: "More navigation" });
  await expect(more).toBeVisible();
  await more.click();
  await expect.poll(() => content.evaluate((el) => el.scrollTop)).toBeGreaterThan(0);
  await content.evaluate((el) => el.scrollTo(0, el.scrollHeight));
  await expect(more).not.toBeVisible();
  await content.evaluate((el) => el.scrollTo(0, 0));
  await expect(more).toBeVisible();
  await page.setViewportSize({ width: 1280, height: 1200 });
  await expect(more).not.toBeVisible();
  await page.getByRole("button", { name: "Search page actions" }).click();
  await expect(page.getByPlaceholder("Search page actions")).toBeVisible();
});

test("starred observation codes can be found by their code", async ({ page }) => {
  const concept = {
    code: "8480-6",
    display: "Systolic blood pressure",
    system: "http://loinc.org",
  };
  await page.route("**/api/v1/valueset/favourites_by_slug/**", (route) =>
    route.fulfill({ json: [concept] }),
  );
  await page.route("**/api/v1/valueset/recent_views_by_slug/**", (route) =>
    route.fulfill({ json: [] }),
  );
  await page.route("**/api/v1/valueset/expand_slug/", (route) =>
    route.fulfill({
      json: { results: [], valueset: { id: "observation-valueset" } },
    }),
  );
  await createQuestionnaireAndOpenBuilder(page, {
    basePath: "/admin/questionnaires",
    title: `Code search regression ${Date.now()}`,
  });
  await addTopLevelQuestion(page, "Blood pressure");
  await page.getByRole("tab", { name: "Coding" }).click();
  await page.getByRole("combobox", { name: "Search for observation codes" }).click();
  const starred = page.getByTestId("valueset-starred");
  await expect(starred).toContainText(concept.display);
  await page.locator('[data-slot="command-input"]').last().fill(concept.code);
  await expect(starred.getByRole("option")).toContainText(concept.display);
});

