import { Ban } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";

import ConfirmActionDialog from "@/components/Common/ConfirmActionDialog";

import mutate from "@/Utils/request/mutate";
import { QuestionnaireResponseStatus } from "@/types/questionnaire/questionnaireResponse";
import resourceQuestionnaireResponseApi, {
  ResourceQuestionnaireResponse,
} from "@/types/questionnaire/resourceQuestionnaireResponseApi";

export function ResourceResponseActions({
  response,
}: {
  response: ResourceQuestionnaireResponse;
}) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [open, setOpen] = useState(false);
  const { mutate: updateStatus, isPending } = useMutation({
    mutationFn: mutate(resourceQuestionnaireResponseApi.update, {
      pathParams: { id: response.id },
    }),
    onSuccess: () => {
      toast.success(t("questionnaire_response_marked_as_entered_in_error"));
      void queryClient.invalidateQueries({ queryKey: ["resourceResponses"] });
      setOpen(false);
    },
  });

  // As with patient response actions, the server enforces the user's
  // submission permission and the configured correction time window.
  if (response.status === QuestionnaireResponseStatus.EnteredInError) {
    return null;
  }

  return (
    <>
      <Button
        type="button"
        variant="ghost"
        className="h-auto min-h-10 whitespace-normal text-red-700 hover:text-red-800"
        disabled={isPending}
        onClick={() => setOpen(true)}
      >
        <Ban className="size-4 shrink-0" />
        {t("mark_as_entered_in_error")}
      </Button>
      <ConfirmActionDialog
        open={open}
        onOpenChange={setOpen}
        title={t("mark_as_entered_in_error")}
        description={t("questionnaire_response_entered_in_error_warning")}
        onConfirm={() =>
          updateStatus({ status: QuestionnaireResponseStatus.EnteredInError })
        }
        confirmText={t("confirm")}
        variant="destructive"
        disabled={isPending}
      />
    </>
  );
}
import type { ContextPathOption } from "@/components/QuestionnaireV2/builder/actionVariables";
import type { ActionInstructionDefinition } from "@/types/questionnaire/actions";

/** These instructions only read their parameters; their registry context
 * predates use from other triggers and does not restrict execution. */
const CONTEXT_INDEPENDENT_INSTRUCTIONS = new Set(["show_message", "logging"]);

export function isInstructionCompatible(
  instruction: ActionInstructionDefinition,
  contextPaths: ContextPathOption[],
): boolean {
  return (
    CONTEXT_INDEPENDENT_INSTRUCTIONS.has(instruction.slug) ||
    contextPaths.some((option) => option.contextType === instruction.context)
  );
}
import { BLOOD_GROUP_CHOICES, GENDER_TYPES } from "@/common/constants";
import type {
  AnswerShape,
  ContextValueVariable,
} from "@/components/QuestionnaireV2/builder/actionVariables";

interface ContextFieldInput {
  shape: AnswerShape;
  date?: boolean;
  options?: { value: string; label: string; translationKey?: string }[];
}

/** The field registry has no value schema yet. Use the patient model's
 * known field types, leaving extension fields on the generic input. */
export function contextFieldInput(
  variable: ContextValueVariable | undefined,
): ContextFieldInput | undefined {
  if (variable?.ownerContextType !== "Patient") return undefined;
  switch (variable.segments.at(-1)) {
    case "age":
    case "year_of_birth":
      return { shape: "number" };
    case "deceased":
      return { shape: "boolean" };
    case "date_of_birth":
      return { shape: "text", date: true };
    case "blood_group":
      return {
        shape: "choice",
        options: BLOOD_GROUP_CHOICES.map(({ id, text }) => ({
          value: id,
          label: text,
          ...(id === "unknown" && { translationKey: "unknown" }),
        })),
      };
    case "gender":
      return {
        shape: "choice",
        options: GENDER_TYPES.map(({ id, text }) => ({
          value: id,
          label: text,
          translationKey: `GENDER__${id}`,
        })),
      };
    case "phone_number":
    case "name":
      return { shape: "text" };
    default:
      return undefined;
  }
}
