import fs from "node:fs";
const saved = JSON.parse(fs.readFileSync("tests/.auth/user.json", "utf8"));
const token = saved.origins[0].localStorage.find((entry) => entry.name === "care_access_token").value;
for (const search of ["8480-6", "Systolic blood pressure"]) {
  const response = await fetch("http://localhost:9000/api/v1/valueset/expand_slug/", {
    method: "POST",
    headers: {"Content-Type":"application/json", Authorization: `Bearer ${token}`},
    body: JSON.stringify({slug:"system-observation", search, count:10}),
  });
  const body = await response.json();
  console.log(JSON.stringify({search, status:response.status, results:body.results?.map(({code,display})=>({code,display})), error:response.ok?undefined:body}));
}

