import {
  BatchRequestBody,
  BatchRequestResponse,
  BatchRequestResult,
} from "@/types/base/batch/batch";
import { handleHttpError } from "@/Utils/request/errorHandler";
import mutate from "@/Utils/request/mutate";
import { ApiRoute, HTTPError, HttpMethod, Type } from "@/Utils/request/types";
import { makeUrl } from "@/Utils/request/utils";
import {
  DefaultError,
  QueryClient,
  useMutation,
  UseMutationOptions,
} from "@tanstack/react-query";

export interface BatchRequestObject<T = unknown> {
  api: ApiRoute<unknown, unknown>;
  pathParams?: Record<string, string>;
  body: T;
  referenceId: string;
}

const batchRequestApi = {
  path: "/api/v1/batch_requests/",
  method: HttpMethod.POST,
  TRes: Type<BatchRequestResponse>(),
  TBody: Type<BatchRequestBody>(),
} as const;

/**
 * Maps an array of {@link BatchRequestObject}s to the body expected by the
 * batch request endpoint.
 */
function buildBatchRequestBody(
  requests: BatchRequestObject[],
): BatchRequestBody {
  return {
    requests: requests.map((request) => ({
      url: makeUrl(request.api.path, undefined, request.pathParams),
      method: request.api.method ?? HttpMethod.GET,
      reference_id: request.referenceId,
      body: request.body,
    })),
  };
}

/**
 * Tells if the error cause is a batch response.
 *
 * The backend runs the batch in one atomic transaction. If one sub-request
 * fails, the backend gives a 4xx/5xx status for the full batch, but it keeps
 * the status and error body of each sub-request in the `results` array. Use
 * this guard to find that shape.
 */
function isBatchResponse(cause: unknown): cause is BatchRequestResponse {
  return (
    typeof cause === "object" &&
    cause !== null &&
    "results" in cause &&
    Array.isArray(cause.results) &&
    cause.results.every((result) => {
      if (typeof result !== "object" || result === null) {
        return false;
      }
      const r = result as Record<string, unknown>;
      return (
        typeof r.reference_id === "string" && typeof r.status_code === "number"
      );
    })
  );
}

/**
 * Sends the error of each failed sub-request to the global error handler.
 *
 * The global error handler cannot read the batch shape. So it shows a wrong
 * "something went wrong" message for the successful sub-requests too. To
 * prevent this, make a new `HTTPError` for each failed sub-request and give
 * it to the global error handler. Each sub-error gets the full handling: the
 * pydantic errors, the structured errors, the 404 detail, and more. The
 * successful sub-requests show no message.
 */
function handleBatchSubErrors(results: BatchRequestResult[]) {
  for (const result of results) {
    if (200 <= result.status_code && result.status_code < 300) {
      continue;
    }

    handleHttpError(
      new HTTPError({
        message: "Request Failed",
        status: result.status_code,
        silent: false,
        cause: (result.data ?? {}) as Record<string, unknown>,
      }),
    );
  }
}

/**
 * A hook to call the batch request API.
 *
 * The backend runs all the given requests in series in one atomic
 * transaction. If one request fails, the backend rolls back all the changes
 * and gives a 4xx/5xx status for the full batch.
 *
 * This hook shows the error of each failed sub-request through the global
 * error handler, and it shows no error for the successful sub-requests. Set
 * `silent` to `true` if the caller handles the errors itself.
 *
 * The original error still goes to the `onError` and `onSettled` callbacks.
 * The batch results are in `error.cause.results`.
 *
 * Example:
 * ```tsx
 * const { mutate: batchRequest, isPending } = useBatchRequest({
 *   onSuccess: ({ results }) => {
 *     toast.success(t("saved"));
 *   },
 * });
 *
 * const submit = () => {
 *   const requests: BatchRequestObject[] = [];
 *   // ... add requests
 *   batchRequest(requests);
 * };
 * ```
 */
export function useBatchRequest<TError = DefaultError, TContext = unknown>(
  options: UseMutationOptions<
    BatchRequestResponse,
    TError,
    BatchRequestObject[],
    TContext
  > & { silent?: boolean },
  queryClient?: QueryClient,
) {
  const { silent, ...mutationOptions } = options;

  return useMutation(
    {
      mutationFn: async (requests: BatchRequestObject[]) => {
        try {
          return await mutate(batchRequestApi)(buildBatchRequestBody(requests));
        } catch (error) {
          // Re-throw any error that is not a batch response so the global
          // error handler and the caller handle it as usual.
          if (!(error instanceof HTTPError) || !isBatchResponse(error.cause)) {
            throw error;
          }

          if (!silent) {
            handleBatchSubErrors(error.cause.results);
          }

          // We still need to throw so the caller treats this mutation as failed.
          throw new HTTPError({
            message: "Batch Request Failed",
            status: error.status,
            silent: true,
            cause: error.cause,
          });
        }
      },
      ...mutationOptions,
    },
    queryClient,
  );
}
import { useQuery } from "@tanstack/react-query";
import { X } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";

import { OrgSelector } from "@/components/Questionnaire/OrgSelector";
import { questionnaireKeys } from "@/components/QuestionnaireV2/queryKeys";

import FacilityOrganizationSelector from "@/pages/Facility/settings/organizations/components/FacilityOrganizationSelector";

import { Organization } from "@/types/organization/organization";
import organizationApi from "@/types/organization/organizationApi";
import { QuestionnaireScope } from "@/types/questionnaire/questionnaire";
import questionnaireApi from "@/types/questionnaire/questionnaireApi";
import query from "@/Utils/request/query";

export interface OrganizationSelection {
  ids: string[];
  /** Labels survive a closed picker or a changed search term. */
  organizations: Pick<Organization, "id" | "name">[];
}

interface OrganizationsFieldProps {
  scope: QuestionnaireScope;
  questionnaireId: string;
  /** When false, the organization list renders read-only (no toggles). */
  canWrite: boolean;
  draft: OrganizationSelection | null;
  onChange: (selection: OrganizationSelection | null) => void;
}

/**
 * Plain labeled field (not a separate card) — Organizations renders as the
 * access control within the questionnaire properties. Edits remain local
 * until the page saves the questionnaire.
 */
function OrganizationsFieldShell({ children }: { children: React.ReactNode }) {
  const { t } = useTranslation();
  return (
    <div className="space-y-2">
      <p className="text-sm font-medium text-gray-800">{t("organizations")}</p>
      {children}
    </div>
  );
}

/**
 * Muted state for when the org endpoint rejects this questionnaire — e.g. a
 * facility-created questionnaire opened through the admin mount, where the
 * instance-level get_organizations endpoint 403s.
 */
function OrganizationsUnavailableCard() {
  const { t } = useTranslation();
  return (
    <OrganizationsFieldShell>
      <p className="text-sm text-gray-500">{t("organizations_unavailable")}</p>
    </OrganizationsFieldShell>
  );
}

export function OrganizationsField({
  scope,
  questionnaireId,
  canWrite,
  draft,
  onChange,
}: OrganizationsFieldProps) {
  if (scope.authContext === "instance") {
    return (
      <InstanceOrganizationsField
        questionnaireId={questionnaireId}
        canWrite={canWrite}
        draft={draft}
        onChange={onChange}
      />
    );
  }
  if (scope.authContext === "facility" && scope.facilityId) {
    return (
      <FacilityOrganizationsField
        facilityId={scope.facilityId}
        questionnaireId={questionnaireId}
        canWrite={canWrite}
        draft={draft}
        onChange={onChange}
      />
    );
  }
  // facility_organization / user contexts: no organization-linking UI exists
  // for these scopes yet, and there is no facilityId to drive the facility
  // selector — render nothing rather than issuing queries with undefined ids.
  return null;
}

function InstanceOrganizationsField({
  questionnaireId,
  canWrite,
  draft,
  onChange,
}: Omit<OrganizationsFieldProps, "scope">) {
  const { t } = useTranslation();
  const [searchQuery, setSearchQuery] = useState("");

  const {
    data: current,
    isLoading,
    isError,
  } = useQuery({
    queryKey: questionnaireKeys.organizations(questionnaireId, "instance"),
    // silent: cross-scope questionnaires 403 here on page load (see
    // OrganizationsUnavailableCard) — surfaced inline, not as a toast.
    queryFn: query(questionnaireApi.getOrganizations, {
      pathParams: { id: questionnaireId },
      silent: true,
    }),
  });

  const { data: available, isLoading: isSearching } = useQuery({
    queryKey: ["organizations", "role", searchQuery],
    queryFn: query.debounced(organizationApi.list, {
      queryParams: { org_type: "role", name: searchQuery || undefined },
    }),
    enabled: canWrite && !isError,
  });

  const selected = draft?.organizations ?? current?.results ?? [];

  if (isError) {
    return <OrganizationsUnavailableCard />;
  }

  const handleToggle = (orgId: string) => {
    const isSelected = selected.some((org) => org.id === orgId);
    let next: OrganizationSelection["organizations"];
    if (isSelected) {
      next = selected.filter((org) => org.id !== orgId);
    } else {
      const orgToAdd = [
        ...(current?.results ?? []),
        ...(available?.results ?? []),
      ].find((org) => org.id === orgId);
      next = orgToAdd ? [...selected, orgToAdd] : selected;
    }
    const ids = next.map((org) => org.id);
    const savedIds = current?.results.map((org) => org.id) ?? [];
    onChange(
      ids.length === savedIds.length && ids.every((id) => savedIds.includes(id))
        ? null
        : { ids, organizations: next },
    );
  };

  return (
    <OrganizationsFieldShell>
      {/* One control: the selected chips render inline inside the same
          bordered box as the search trigger, not in a separate dashed box. */}
      <div className="flex flex-wrap items-center gap-2 rounded-md border border-gray-200 p-1.5">
        {!isLoading && !canWrite && selected.length === 0 && (
          <p className="px-1.5 py-1 text-sm text-gray-500">
            {t("no_organizations_selected")}
          </p>
        )}
        {selected.map((org) => (
          <Badge key={org.id} variant="secondary" className="gap-1">
            {org.name}
            {canWrite && (
              <button
                type="button"
                onClick={() => handleToggle(org.id)}
                aria-label={t("remove_organization")}
              >
                <X className="size-3" />
              </button>
            )}
          </Badge>
        ))}
        {canWrite && !isLoading && (
          <OrgSelector
            selected={selected.map((org) => org.id)}
            onToggle={handleToggle}
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
            isLoading={isSearching}
            organizations={available}
            triggerClassName="h-8 w-auto min-w-40 flex-1 border-0 px-1.5 font-normal text-gray-500 shadow-none"
          />
        )}
      </div>
    </OrganizationsFieldShell>
  );
}

function FacilityOrganizationsField({
  facilityId,
  questionnaireId,
  canWrite,
  draft,
  onChange,
}: Omit<OrganizationsFieldProps, "scope"> & { facilityId: string }) {
  const { t } = useTranslation();

  const {
    data: current,
    isError,
    isLoading,
  } = useQuery({
    queryKey: questionnaireKeys.organizations(questionnaireId, "facility"),
    // silent for the same cross-scope reason as the instance variant.
    queryFn: query(questionnaireApi.getFacilityOrganizations, {
      pathParams: { id: questionnaireId },
