interface ProviderProps {
  questionnaire: QuestionnaireRead;
  mode: FormMode;
  subject?: RendererSubject;
  revealHidden?: boolean;
  inert?: boolean;
  /** See `FormContextValue.frozen`. Defaults false — only the fill host's
   *  submit window ever sets it. */
  frozen?: boolean;
  /**
