import { ChevronDown } from "lucide-react";
import { type ReactNode, useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { SidebarContent } from "@/components/ui/sidebar";

interface ScrollableSidebarContentProps {
  children: ReactNode;
}

export function ScrollableSidebarContent({
  children,
}: ScrollableSidebarContentProps) {
  const { t } = useTranslation();
  const containerRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const [hasMore, setHasMore] = useState(false);

  useEffect(() => {
    const container = containerRef.current;
    const content = contentRef.current;
    if (!container || !content) return;

    const updateOverflow = () => {
      setHasMore(
        container.scrollHeight - container.scrollTop - container.clientHeight >
          2,
      );
    };
    const observer = new ResizeObserver(updateOverflow);
    observer.observe(container);
    observer.observe(content);
    container.addEventListener("scroll", updateOverflow, { passive: true });
    updateOverflow();
    return () => {
      observer.disconnect();
      container.removeEventListener("scroll", updateOverflow);
    };
  }, []);

  return (
    <div className="relative flex min-h-0 flex-1 flex-col">
      <SidebarContent
        ref={containerRef}
        className="gap-2 bg-neutral-100 text-neutral-950"
      >
        <div ref={contentRef} className="flex flex-col gap-2 pb-9">
          {children}
        </div>
      </SidebarContent>
      {hasMore && (
        <div className="pointer-events-none absolute inset-x-0 bottom-0 flex justify-center bg-gradient-to-t from-neutral-100 via-neutral-100/95 to-transparent pt-4 pb-1">
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="pointer-events-auto h-7 gap-1 rounded-full bg-white text-xs"
            onClick={() =>
              containerRef.current?.scrollBy({
                top: Math.max(120, containerRef.current.clientHeight * 0.6),
                behavior: window.matchMedia("(prefers-reduced-motion: reduce)")
                  .matches
                  ? "instant"
                  : "smooth",
              })
            }
          >
            {t("more_navigation")}
            <ChevronDown aria-hidden className="size-3" />
          </Button>
        </div>
      )}
    </div>
  );
}
import type { ContextPathOption } from "@/components/QuestionnaireV2/builder/actionVariables";
import type { ActionInstructionDefinition } from "@/types/questionnaire/actions";

/** These instructions only read their parameters; their registry context
 * predates use from other triggers and does not restrict execution. */
const CONTEXT_INDEPENDENT_INSTRUCTIONS = new Set(["show_message", "logging"]);

export function isInstructionCompatible(
  instruction: ActionInstructionDefinition,
  contextPaths: ContextPathOption[],
): boolean {
  return (
    CONTEXT_INDEPENDENT_INSTRUCTIONS.has(instruction.slug) ||
    contextPaths.some((option) => option.contextType === instruction.context)
  );
}
import { BLOOD_GROUP_CHOICES, GENDER_TYPES } from "@/common/constants";
import type {
  AnswerShape,
  ContextValueVariable,
} from "@/components/QuestionnaireV2/builder/actionVariables";

interface ContextFieldInput {
  shape: AnswerShape;
  date?: boolean;
  options?: { value: string; label: string; translationKey?: string }[];
}

/** The field registry has no value schema yet. Use the patient model's
 * known field types, leaving extension fields on the generic input. */
export function contextFieldInput(
  variable: ContextValueVariable | undefined,
): ContextFieldInput | undefined {
  if (variable?.ownerContextType !== "Patient") return undefined;
  switch (variable.segments.at(-1)) {
    case "age":
    case "year_of_birth":
      return { shape: "number" };
    case "deceased":
      return { shape: "boolean" };
    case "date_of_birth":
      return { shape: "text", date: true };
    case "blood_group":
      return {
        shape: "choice",
        options: BLOOD_GROUP_CHOICES.map(({ id, text }) => ({
          value: id,
          label: text,
          ...(id === "unknown" && { translationKey: "unknown" }),
        })),
      };
    case "gender":
      return {
        shape: "choice",
        options: GENDER_TYPES.map(({ id, text }) => ({
          value: id,
          label: text,
