                  <OrganizationsField
                    scope={scope}
                    questionnaireId={id}
                    canWrite={canWrite}
                    draft={organizationDraft}
                    onChange={setOrganizationDraft}
                  />
                  {canWrite && (
                    <LabeledActionButton
                      label={t("edit_questions")}
