import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { questionnaireKeys } from "@/components/QuestionnaireV2/queryKeys";
import { useBatchRequest } from "@/Utils/request/batch";

import {
  QuestionnaireRead,
  QuestionnaireScope,
  QuestionnaireUpdate,
} from "@/types/questionnaire/questionnaire";
import questionnaireApi from "@/types/questionnaire/questionnaireApi";
import mutate from "@/Utils/request/mutate";

interface OrganizationUpdate {
  scope: QuestionnaireScope;
  ids: string[];
}

/** Metadata and pending organization access changes save atomically. */
export function useUpdateQuestionnaire(
  id: string,
  onSaved?: (updated: QuestionnaireRead) => void,
) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();

  const onSuccess = (updated: QuestionnaireRead) => {
    queryClient.setQueryData(questionnaireKeys.detail(id), updated);
    queryClient.invalidateQueries({ queryKey: questionnaireKeys.all });
    toast.success(t("questionnaire_updated_successfully"));
    onSaved?.(updated);
  };

  const update = useMutation({
    mutationFn: mutate(questionnaireApi.update, { pathParams: { id } }),
    onSuccess,
  });
  const batch = useBatchRequest({
    onSuccess: ({ results }) => {
      // This reference is always the typed questionnaire update request below.
      const updated = results.find(
        (result) => result.reference_id === "questionnaire",
      )?.data as QuestionnaireRead;
      onSuccess(updated);
    },
  });

  return {
    isPending: update.isPending || batch.isPending,
    mutate: (
      body: QuestionnaireUpdate,
      organizations?: OrganizationUpdate,
      onCallSaved?: (updated: QuestionnaireRead) => void,
    ) => {
      if (!organizations) {
        update.mutate(body, { onSuccess: onCallSaved });
        return;
      }
      const facility = organizations.scope.authContext === "facility";
      batch.mutate(
        [
          {
            api: questionnaireApi.update,
            pathParams: { id },
            body,
            referenceId: "questionnaire",
          },
          {
            api: facility
              ? questionnaireApi.setFacilityOrganizations
              : questionnaireApi.setOrganizations,
            pathParams: { id },
            body: facility
              ? { facility_organizations: organizations.ids }
              : { organizations: organizations.ids },
            referenceId: "organizations",
          },
        ],
        {
          onSuccess: ({ results }) => {
            const updated = results.find(
              (result) => result.reference_id === "questionnaire",
            )?.data as QuestionnaireRead;
            onCallSaved?.(updated);
          },
        },
      );
    },
  };
}
        handleConfirmSelection(singleOrg);
      }
    }
  }, [
    getCurrentLevelOrganizations,
    handleConfirmSelection,
    navigationLevels,
    facilityOrgSearch,
    selectedOrganizations,
    isLoadingRoot,
    isLoadingPreferred,
    preferredOrgIds.length,
    currentOrganizations,
    props.optional,
    isLoadingPreferred,
    preferredOrgIds.length,
  ]);

  useEffect(() => {
    if (value && value.length > 0) {
      const resolvedOrganizations = value
        .map((id) => currentOrganizations?.find((org) => org.id === id))
        .filter((org) => org !== undefined);
      if (resolvedOrganizations.length > 0) {
        setSelectedOrganizations(resolvedOrganizations);
      }
    } else {
      setSelectedOrganizations([]);
      // Reset the auto-select flag when value is cleared (e.g., form reset)
      // setHasAutoSelectedPreferred(false);
    }
  }, [value, currentOrganizations, showAllOrgs]);

  // Auto-select preferred departments
  useEffect(() => {
    if (
      favoriteList &&
      preferredOrganizations?.results &&
      preferredOrganizations.results.length > 0 &&
      selectedOrganizations.length === 0 &&
      !hasAutoSelectedPreferred &&
      !value?.length
    ) {
      const orgsToSelect = singleSelection
        ? [preferredOrganizations.results[0]]
        : preferredOrganizations.results;
"}

