import { useQuery } from "@tanstack/react-query";
import { Plus, Zap } from "lucide-react";
import { navigate } from "raviger";
import { useTranslation } from "react-i18next";

import { TableSkeleton } from "@/components/Common/SkeletonLoading";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

import Page from "@/components/Common/Page";

import useFilters from "@/hooks/useFilters";

import actionConfigurationApi from "@/types/actions/actionConfigurationApi";
import { isSupportedActionConfigurationContext } from "@/types/actions/actionConfiguration";
import query from "@/Utils/request/query";

import { actionContextLabel } from "./labels";
import { actionConfigurationKeys } from "./queryKeys";

export const ADMIN_ACTIONS_PATH = "/admin/actions";

/**
 * Instance-level action configurations: what runs when an appointment is
 * booked. One row per supported
 * configuration; the row opens its editor.
 */
export function ActionConfigurationList() {
  const { t } = useTranslation();
  const { qParams, Pagination, resultsPerPage } = useFilters({
    limit: 15,
    disableCache: true,
  });

  const { data: response, isLoading } = useQuery({
    queryKey: actionConfigurationKeys.list({ supportedContexts: true }),
    // The API has no context filter. Load every page before filtering so
    // unsupported records cannot leave empty pages or inflate the count.
    queryFn: query.paginated(actionConfigurationApi.list),
  });
  const supportedConfigurations = (response?.results ?? []).filter((configuration) =>
    isSupportedActionConfigurationContext(configuration.action_context),
  );
  const offset = ((qParams.page || 1) - 1) * resultsPerPage;
  const configurations = supportedConfigurations.slice(offset, offset + resultsPerPage);

  return (
    <Page title={t("action_configurations")} hideTitleOnPage>
      <div className="space-y-4">
        <div className="flex flex-col gap-3 md:flex-row md:items-start md:justify-between">
          <div>
            <h1 className="text-xl font-bold text-gray-900">
              {t("action_configurations")}
            </h1>
            <p className="max-w-2xl text-sm text-gray-500">
              {t("action_configurations_description")}
            </p>
          </div>
          <Button onClick={() => navigate(`${ADMIN_ACTIONS_PATH}/new`)}>
            <Plus className="size-4" />
            {t("action_configuration_new")}
          </Button>
        </div>

        {isLoading ? (
          <TableSkeleton count={5} />
        ) : configurations.length === 0 ? (
          <div className="rounded-lg border border-dashed border-gray-300 p-8 text-center">
            <Zap aria-hidden className="mx-auto mb-2 size-6 text-gray-400" />
            <p className="text-sm font-medium text-gray-900">
              {t("action_configurations_empty")}
            </p>
            <p className="mb-4 text-sm text-gray-500">
              {t("action_configurations_empty_hint")}
            </p>
            <Button onClick={() => navigate(`${ADMIN_ACTIONS_PATH}/new`)}>
              <Plus className="size-4" />
              {t("action_configuration_new")}
            </Button>
          </div>
        ) : (
          <div className="overflow-hidden rounded-lg border border-gray-200 bg-white">
            <Table className="table-fixed">
              <TableHeader>
                <TableRow className="bg-gray-50 hover:bg-gray-50">
                  <TableHead className="h-8 w-[40%] text-xs font-medium text-gray-500">
                    {t("name")}
                  </TableHead>
                  <TableHead className="h-8 w-[20%] text-xs font-medium text-gray-500">
                    {t("action_configuration_context")}
                  </TableHead>
                  <TableHead className="h-8 w-[20%] text-xs font-medium text-gray-500">
                    {t("actions")}
                  </TableHead>
                  <TableHead className="h-8 w-[20%] text-xs font-medium text-gray-500">
                    {t("action_configuration_on_demand")}
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {configurations.map((configuration) => (
                  <TableRow
                    key={configuration.id}
                    className="cursor-pointer"
                    onClick={() =>
                      navigate(`${ADMIN_ACTIONS_PATH}/${configuration.id}`)
                    }
                  >
                    <TableCell className="py-2.5">
                      <span className="block truncate text-sm font-medium text-gray-900">
                        {configuration.name}
                      </span>
                      {configuration.description && (
                        <span className="block truncate text-xs text-gray-500">
                          {configuration.description}
                        </span>
                      )}
                    </TableCell>
                    <TableCell className="py-2.5">
                      <Badge variant="secondary">
                        {actionContextLabel(configuration.action_context, t)}
                      </Badge>
                    </TableCell>
                    <TableCell className="py-2.5 text-sm text-gray-700">
                      {t("action_count", {
                        count: configuration.actions?.length ?? 0,
                      })}
                    </TableCell>
                    <TableCell className="py-2.5 text-sm text-gray-700">
                      {configuration.performable ? t("yes") : t("no")}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}

        <Pagination totalCount={supportedConfigurations.length} />
      </div>
    </Page>
  );
}
import { HttpMethod, PaginatedResponse, Type } from "@/Utils/request/types";

import {
  ActionConfigurationCreate,
  ActionConfigurationRead,
  ActionConfigurationRetrieve,
  ActionConfigurationUpdate,
} from "./actionConfiguration";

export default {
  list: {
    path: "/api/v1/action_configuration/",
    method: HttpMethod.GET,
    TRes: Type<PaginatedResponse<ActionConfigurationRead>>(),
  },
  retrieve: {
    path: "/api/v1/action_configuration/{id}/",
    method: HttpMethod.GET,
    TRes: Type<ActionConfigurationRetrieve>(),
  },
  create: {
    path: "/api/v1/action_configuration/",
    method: HttpMethod.POST,
    TBody: Type<ActionConfigurationCreate>(),
    TRes: Type<ActionConfigurationRead>(),
  },
  update: {
    path: "/api/v1/action_configuration/{id}/",
    method: HttpMethod.PUT,
    TBody: Type<ActionConfigurationUpdate>(),
    TRes: Type<ActionConfigurationRead>(),
  },
  delete: {
    path: "/api/v1/action_configuration/{id}/",
    method: HttpMethod.DELETE,
    TRes: Type<Record<string, never>>(),
  },
} as const;
import { useQuery } from "@tanstack/react-query";
import {
  Archive,
  ClipboardList,
  Eye,
  FileCheck,
  NotepadTextDashed,
  Plus,
  Search,
} from "lucide-react";
import { navigate } from "raviger";
import { useTranslation } from "react-i18next";

import { TableSkeleton } from "@/components/Common/SkeletonLoading";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/ui/empty-state";
import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

import { questionnaireKeys } from "@/components/QuestionnaireV2/queryKeys";
import { useCanWriteQuestionnaire } from "@/components/QuestionnaireV2/useCanWriteQuestionnaire";

import useFilters from "@/hooks/useFilters";

import { cn } from "@/lib/utils";
import {
  QUESTIONNAIRE_STATUSES,
  QuestionStatus,
  QuestionnaireScope,
} from "@/types/questionnaire/questionnaire";
import questionnaireApi from "@/types/questionnaire/questionnaireApi";
import query from "@/Utils/request/query";

const STATUS_TAB_ICONS: Record<QuestionStatus, React.ReactNode> = {
  active: <FileCheck className="size-4" />,
  draft: <NotepadTextDashed className="size-4" />,
  retired: <Archive className="size-4" />,
};

/** Tab order mirrors the canonical status array, so adding a status surfaces
 *  a tab (and a compile error here until it gets an icon). */
const STATUS_TABS = QUESTIONNAIRE_STATUSES.map((value) => ({
  value,
  icon: STATUS_TAB_ICONS[value],
}));

export function QuestionnaireListPage({
  scope,
}: {
  scope: QuestionnaireScope;
}) {
  const { t } = useTranslation();
  const { canWrite: canWriteQuestionnaire, isLoading: isPermissionLoading } =
    useCanWriteQuestionnaire(scope);
  const { qParams, updateQuery, Pagination, resultsPerPage } = useFilters({
    limit: 15,
    disableCache: true,
    defaultQueryParams: { status: "active" },
  });

  const { data: response, isLoading } = useQuery({
    queryKey: questionnaireKeys.list(scope, qParams),
    queryFn: query.debounced(questionnaireApi.list, {
      queryParams: {
        limit: resultsPerPage,
        offset: ((qParams.page || 1) - 1) * resultsPerPage,
        title: qParams.search,
        status: qParams.status,
        facility: scope.facilityId,
        auth_context: scope.authContext,
      },
    }),
  });

  const questionnaires = response?.results ?? [];

  return (
    <div className="space-y-4">
      <div>
        <h1 className="text-xl font-bold text-gray-900">
          {t("questionnaire_other")}
        </h1>
        <p className="text-sm text-gray-500">
          {t("manage_and_view_questionnaires")}
        </p>
      </div>

      <div className="flex flex-wrap items-center gap-3">
        <div
          role="radiogroup"
          aria-label={t("status")}
          className="flex rounded-md border border-gray-200 bg-gray-50 p-0.5"
        >
          {STATUS_TABS.map((tab) => (
            <button
              key={tab.value}
              type="button"
              role="radio"
              aria-checked={qParams.status === tab.value}
              onClick={() => updateQuery({ status: tab.value })}
              className={cn(
                "flex items-center gap-1.5 rounded px-3 py-1.5 text-sm",
                qParams.status === tab.value
                  ? "border border-gray-200 bg-white font-medium text-gray-900 shadow-sm"
                  : "text-gray-500 hover:text-gray-700",
              )}
            >
              {tab.icon}
              {t(tab.value)}
            </button>
          ))}
        </div>

        <div className="relative w-full md:w-[300px]">
          <Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-gray-400" />
          <Input
            placeholder={t("search_questionnaires")}
            value={qParams.search || ""}
            onChange={(e) =>
              updateQuery({ search: e.target.value || undefined })
            }
            className="w-full pl-9"
          />
        </div>

        {canWriteQuestionnaire && (
          <Button
            className="w-full md:ml-auto md:w-auto"
            onClick={() => navigate(`${scope.basePath}/new`)}
          >
            <Plus className="mr-2 size-4" />
            {t("create_questionnaire")}
          </Button>
        )}
      </div>

      {isLoading || isPermissionLoading ? (
        <TableSkeleton count={10} />
      ) : questionnaires.length === 0 ? (
        <EmptyState
          icon={<ClipboardList className="size-6 text-primary" />}
          title={t("no_questionnaires_found")}
          description={t("adjust_questionnaire_filters")}
          action={
            canWriteQuestionnaire ? (
              <Button onClick={() => navigate(`${scope.basePath}/new`)}>
                <Plus className="mr-2 size-4" />
                {t("create_questionnaire")}
              </Button>
            ) : undefined
          }
        />
      ) : (
        <div className="hidden rounded-lg border md:block">
          <Table className="table-fixed">
            <TableHeader>
              <TableRow className="bg-gray-50 hover:bg-gray-50">
                <TableHead className="h-8 w-[30%] text-xs font-medium text-gray-500">
                  {t("title")}
                </TableHead>
                <TableHead className="h-8 w-[50%] text-xs font-medium text-gray-500">
                  {t("description")}
                </TableHead>
                <TableHead className="h-8 w-[20%] text-xs font-medium text-gray-500">
                  {t("slug")}
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {questionnaires.map((questionnaire) => (
                <TableRow
                  key={questionnaire.id}
                  role="link"
                  tabIndex={0}
                  className="group cursor-pointer focus-visible:bg-gray-100/50 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-inset focus-visible:ring-primary-500"
                  onClick={() =>
                    navigate(`${scope.basePath}/${questionnaire.id}`)
                  }
                  onKeyDown={(e) => {
                    if (e.target !== e.currentTarget) return;
                    if (e.key === "Enter" || e.key === " ") {
                      e.preventDefault();
                      navigate(`${scope.basePath}/${questionnaire.id}`);
                    }
                  }}
                >
                  <TableCell className="truncate font-medium">
                    {questionnaire.title}
                  </TableCell>
                  <TableCell className="text-gray-500">
                    <div className="flex items-center justify-between gap-2">
                      <span className="min-w-0 flex-1 truncate">
                        {questionnaire.description}
                      </span>
                      <Button
                        variant="outline"
                        size="sm"
                        className="invisible shrink-0 group-hover:visible"
                        onClick={(e) => {
                          e.stopPropagation();
                          navigate(`${scope.basePath}/${questionnaire.id}`);
                        }}
                      >
                        <Eye className="mr-1 size-4" />
                        {t("see_details")}
                      </Button>
                    </div>
                  </TableCell>
                  <TableCell>
                    <Badge
                      variant="secondary"
                      className="max-w-full truncate font-normal"
                    >
                      {questionnaire.slug}
                    </Badge>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      )}
      {/* Mobile cards */}
      {!isLoading && !isPermissionLoading && questionnaires.length > 0 && (
        <div className="grid gap-3 md:hidden">
          {questionnaires.map((questionnaire) => (
            <button
              key={questionnaire.id}
              type="button"
              className="rounded-lg border p-4 text-left"
              onClick={() => navigate(`${scope.basePath}/${questionnaire.id}`)}
            >
              <p className="font-medium">{questionnaire.title}</p>
              <p className="mt-1 line-clamp-2 text-sm text-gray-500">
                {questionnaire.description}
              </p>
              <Badge variant="secondary" className="mt-2 font-normal">
                {questionnaire.slug}
              </Badge>
            </button>
          ))}
        </div>
      )}
      <div className="flex justify-center">
        <Pagination totalCount={response?.count || 0} />
      </div>
    </div>
  );
}

