                {questionnaire.description}
              </p>
              <Badge variant="secondary" className="mt-2 font-normal">
                {questionnaire.slug}
              </Badge>
            </button>
          ))}
        </div>
      )}
      <div className="flex justify-center">
        <Pagination totalCount={response?.count || 0} />
      </div>
    </div>
  );
}

