      page.getByRole("row").filter({ hasText: `${prefix} appointment 15` }),
    ).toBeVisible();
    await expect(page.locator("#next-pages")).toBeDisabled();
  });

  test("preserves legacy unsupported configurations without offering edits", async ({
    page,
  }) => {
